<template><div class="fixed inset-0 z-[60] overflow-y-auto bg-[#f6f8f7] p-4 sm:p-6 dark:bg-dark-950"><div class="mx-auto max-w-[1800px]"><div class="mb-4 flex items-center justify-between"><div><h2 class="text-xl font-semibold">{{ t('admin.accounts.pelicanTest.history') }}</h2><p class="text-sm text-gray-500">{{ t('admin.accounts.pelicanTest.dashboardHint') }}</p></div><button class="btn btn-secondary" @click="$emit('close')">{{ t('common.close') }}</button></div><div v-if="loading" class="py-20 text-center text-sm text-gray-500">{{ t('common.loading') }}...</div><div v-else-if="cards.length" class="grid grid-cols-1 gap-4 lg:grid-cols-2 2xl:grid-cols-4"><article v-for="card in cards" :key="card.account.id" class="cursor-pointer overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-sm transition hover:-translate-y-0.5 hover:border-primary-300 hover:shadow-md dark:border-dark-700 dark:bg-dark-800" @click="card.result && (selected = card.result)"><div class="p-4"><h3 class="font-semibold">{{ card.account.name }}</h3><p class="text-xs text-gray-500">#{{ card.account.id }} · {{ card.result ? t('admin.accounts.pelicanTest.sourceScheduled') : t('admin.accounts.pelicanTest.sourceManual') }}</p><div v-if="card.result" class="mt-3 space-y-1 text-xs text-gray-500"><div>{{ card.result.pelican_config?.model_id }} / {{ card.result.pelican_config?.reasoning_effort }} · {{ t('admin.accounts.pelicanTest.duration') }} {{ (card.result.latency_ms / 1000).toFixed(1) }} s</div><div>{{ t('admin.accounts.pelicanTest.generatedAt') }}：{{ formatDate(card.result.started_at) }}</div></div><div v-if="card.result?.response_text" class="mt-3 aspect-[4/3] overflow-hidden rounded-xl"><iframe :srcdoc="extractHtml(card.result.response_text)" class="h-full w-full border-0" sandbox="allow-scripts" referrerpolicy="no-referrer" /></div><div v-else class="mt-3 flex aspect-[4/3] items-center justify-center rounded-xl bg-gray-50 text-sm text-gray-400">{{ t('admin.accounts.pelicanTest.noHistory') }}</div></div><div class="flex items-center justify-between border-t px-4 py-3 text-sm"><span class="text-primary-600">{{ t('admin.accounts.pelicanTest.preview') }}</span><span class="text-gray-500">{{ card.plan ? `Cron ${card.plan.cron_expression}` : '—' }}</span></div></article></div><div v-else class="rounded-xl border border-dashed border-gray-300 bg-white py-20 text-center text-sm text-gray-500">{{ t('admin.accounts.pelicanTest.noHistory') }}</div><div v-if="selected" class="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-4" @click.self="selected = null"><div class="flex h-full w-full max-w-6xl flex-col overflow-hidden rounded-xl bg-white"><div class="flex items-center justify-between border-b px-4 py-3"><span class="text-sm font-medium">{{ selected.pelican_config?.model_id }} / {{ selected.pelican_config?.reasoning_effort }} · {{ (selected.latency_ms / 1000).toFixed(1) }} s</span><button class="btn btn-secondary" @click="selected = null">{{ t('common.close') }}</button></div><iframe :srcdoc="extractHtml(selected.response_text)" class="min-h-0 flex-1 w-full border-0" sandbox="allow-scripts" referrerpolicy="no-referrer" /></div></div></div></template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { scheduledTestsAPI } from '@/api/admin/scheduledTests'
import type { AccountListItem, ScheduledTestPlan, ScheduledTestResult } from '@/types'
const props = defineProps<{ accounts: AccountListItem[] }>(); const selected = ref<ScheduledTestResult | null>(null); defineEmits<{ close: []; preview: [result: ScheduledTestResult] }>(); const { t } = useI18n(); const loading = ref(true)
const cards = ref<Array<{ account: AccountListItem; plan: ScheduledTestPlan | null; result: ScheduledTestResult | null }>>([])
function formatDate(value: string) { return new Intl.DateTimeFormat(undefined, { dateStyle: 'short', timeStyle: 'medium' }).format(new Date(value)) }
function extractHtml(raw: string) { let html = raw.trim(); const start = html.search(/<!doctype html|<html|<svg/i); if (start >= 0) html = html.slice(start); if (/<svg[\s>]/i.test(html) && !/<html[\s>]/i.test(html)) html = `<!doctype html><html><body>${html}</body></html>`; return html }
onMounted(async () => { cards.value = (await Promise.all(props.accounts.map(async account => { const plans = await scheduledTestsAPI.listByAccount(account.id); const plan = plans.find(item => item.pelican_config) || null; const results = plan ? await scheduledTestsAPI.listResults(plan.id, 1, true) : []; return { account, plan, result: results[0] || null } }))).filter(card => card.result); loading.value = false })
</script>
